BUSINESS_HTML=r'''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Panther Peptides Command Center</title><style>:root{--b:#050b13;--p:#0b1727;--l:#24415f;--t:#eef6ff;--m:#91a9c0;--g:#35d39a;--r:#ff7185;--a:#f0b64b}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% -20%,#17375c,#07111f 38%,#040910);color:var(--t);font:15px system-ui;min-height:100vh}.w{max-width:1650px;margin:auto;padding:20px}.top,.row,.actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.top{justify-content:space-between}.logo{width:48px;height:48px;border-radius:14px;background:linear-gradient(135deg,#4b9dff,#53dfc0);display:grid;place-items:center;color:#05101d;font-weight:900}h1,h2,h3{margin:0}.muted{color:var(--m)}.card{background:linear-gradient(180deg,#0f2035,#091626);border:1px solid var(--l);border-radius:17px;padding:18px}.btn{border:1px solid #315779;background:#10243d;color:white;padding:10px 14px;border-radius:10px;font-weight:750;cursor:pointer}.yes{background:#123d32;border-color:#2c8068}.no{background:#431b25;border-color:#8c3448}.primary{background:#174d8b;border-color:#367fc6}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:16px 0}.metric b{display:block;font-size:25px}.grid{display:grid;grid-template-columns:1.45fr .75fr;gap:16px}.approval{border:2px solid var(--a);box-shadow:0 0 30px #f0b64b22;margin:16px 0}.approval h2{color:#ffd98c}.question{font-size:20px;font-weight:800;margin:12px 0}.field{width:100%;background:#06111f;border:1px solid #315779;color:white;border-radius:11px;padding:12px}.strategy{display:grid;grid-template-columns:1fr auto;gap:9px;margin:14px 0}.event{border:1px solid #203b57;border-radius:12px;padding:11px;margin-top:8px;background:#081522}.pill{display:inline-block;border:1px solid #365a7c;border-radius:999px;padding:4px 8px;font-size:12px}.available,.completed{color:#bdf5df;border-color:#286b59}.awaiting_approval{color:#ffdc91;border-color:#8a6723}.blocked{color:#ffabb8;border-color:#8c3448}.tabs{display:flex;gap:8px;margin:14px 0}.tab.active{outline:2px solid #4b9dff}.hidden{display:none}.table{overflow:auto}table{width:100%;border-collapse:collapse;min-width:700px}th,td{padding:10px;border-bottom:1px solid #1d354e;text-align:left}.login{max-width:500px;margin:10vh auto}.banner{margin:14px 0;padding:10px 14px;border:1px solid #285f51;border-radius:12px;background:#0d2923;color:#c8f5e4}@media(max-width:900px){.metrics{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.strategy{grid-template-columns:1fr}.w{padding:11px}}</style></head><body><div class="w"><div class="top"><div class="row"><div class="logo">PP</div><div><h1>Panther Peptides</h1><div class="muted">Jarvis Autonomous Business Command Center · <span id="ver"></span></div></div></div><div class="actions"><span id="state" class="pill">connecting</span><a class="btn" href="/jarvis">Voice Console</a></div></div><div id="login" class="card login hidden"><h2>Owner Access</h2><p><input id="pw" class="field" type="password" placeholder="Owner password"></p><button class="btn primary" onclick="login()">Open</button><p id="err"></p></div><main id="app"><div class="banner">FOR RESEARCH USE ONLY — NOT FOR HUMAN OR VETERINARY USE · Jarvis may plan and execute available business actions autonomously. Owner decisions are presented one at a time.</div><section id="approval" class="card approval hidden"><div class="muted">JARVIS NEEDS ONE DECISION</div><h2 id="aqtitle"></h2><div id="aquestion" class="question"></div><div id="arationale" class="muted"></div><p id="acost"></p><div class="actions"><button class="btn yes" onclick="decide(true)">✓ APPROVE</button><button class="btn no" onclick="decide(false)">✕ DENY</button></div></section><div class="strategy"><input id="objective" class="field" placeholder="Give Jarvis a business objective — e.g. Plan and execute our launch strategy" onkeydown="if(event.key==='Enter')runObjective()"><button class="btn primary" onclick="runObjective()">Run Autonomously</button></div><div class="metrics"><div class="card metric"><span class="muted">Available units</span><b id="avail">—</b></div><div class="card metric"><span class="muted">Held / quarantine</span><b id="held">—</b></div><div class="card metric"><span class="muted">Active objectives</span><b id="active">—</b></div><div class="card metric"><span class="muted">Awaiting approval</span><b id="waiting">—</b></div><div class="card metric"><span class="muted">Knowledge files</span><b id="knowledge">—</b></div></div><div class="tabs"><button class="btn tab active" onclick="tab('ops',this)">Strategy & Operations</button><button class="btn tab" onclick="tab('inv',this)">Available Inventory</button><button class="btn tab" onclick="tab('know',this)">Knowledge</button></div><section id="ops" class="grid"><div class="card"><h2>Jarvis Objectives</h2><div id="objectives"></div></div><div class="card"><h2>Recent Activity</h2><div id="events"></div></div></section><section id="inv" class="card hidden"><h2>Available Inventory</h2><p class="muted">Held and quarantined lots are hidden from this operating view.</p><div class="table"><table><thead><tr><th>Product</th><th>Lot</th><th>Qty</th><th>Docs</th></tr></thead><tbody id="inventory"></tbody></table></div></section><section id="know" class="card hidden"><h2>Expand Jarvis Knowledge</h2><p class="muted">Upload operating references, SOPs, product and supplier information, PDFs, CSVs, Markdown and text.</p><form onsubmit="uploadKnowledge(event)"><input id="kf" class="field" type="file" required><p><input id="kc" class="field" placeholder="Category"></p><p><input id="kt" class="field" placeholder="Tags"></p><button class="btn primary">Add Knowledge</button></form><div id="kstat" class="muted"></div></section></main></div><script>const $=x=>document.getElementById(x);let D,A;async function api(u,o={}){let r=await fetch(u,{...o,cache:'no-store'}),d=await r.json().catch(()=>({}));if(r.status===401){$('login').classList.remove('hidden');$('app').classList.add('hidden');throw Error('login')}if(!r.ok)throw Error(d.detail||d.error||r.status);return d}function e(s){return String(s??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}async function login(){try{await api('/auth/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({password:$('pw').value})});$('login').classList.add('hidden');$('app').classList.remove('hidden');load()}catch(x){$('err').textContent=x.message}}function tab(id,b){['ops','inv','know'].forEach(x=>$(x).classList.toggle('hidden',x!==id));document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active')}async function load(){try{let b=await api('/client/bootstrap');$('ver').textContent='v'+b.version;D=await api('/business/dashboard');let s=D.summary,r=D.runtime||{};$('avail').textContent=s.released_units;$('held').textContent=s.quarantined_units;$('active').textContent=(r.queued||0)+(r.running||0);$('waiting').textContent=r.awaiting_approval||0;$('knowledge').textContent=(D.knowledge||{}).files||0;$('state').textContent=r.worker_alive&&r.watchdog_alive?'Jarvis online':'Jarvis attention';$('state').className='pill '+(r.worker_alive?'available':'blocked');render();renderApproval(D.approval)}catch(x){if(x.message!=='login')console.error(x)}}function render(){let o=D.objectives||[];$('objectives').innerHTML=o.slice(0,15).map(x=>`<div class="event"><b>#${x.id} ${e(x.title)}</b><div><span class="pill ${e(x.state)}">${e(x.state)}</span> step ${x.step}/${x.max_steps}</div>${x.blocked_reason?`<div class="muted">${e(x.blocked_reason)}</div>`:''}</div>`).join('')||'<p class="muted">No objectives yet.</p>';$('events').innerHTML=(D.events||[]).slice(0,10).map(x=>`<div class="event"><b>${e(x.title)}</b><div class="muted">${e(x.detail||'')}</div></div>`).join('');let inv=(D.inventory||[]).filter(x=>['available','released','active'].includes(String(x.status).toLowerCase()));$('inventory').innerHTML=inv.map(x=>`<tr><td><b>${e(x.product)}</b></td><td>${e(x.lot_code||'—')}</td><td>${e(x.quantity)}</td><td>${e(x.coa_status||'unknown')}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">No available inventory.</td></tr>';let k=D.knowledge||{};$('kstat').textContent=`${k.files||0} files · ${Number(k.characters||0).toLocaleString()} indexed characters`}function renderApproval(a){A=a;$('approval').classList.toggle('hidden',!a);if(!a)return;let p=a.payload||{};$('aqtitle').textContent=a.objective_title||'Owner decision';$('aquestion').textContent=p.question||a.action;$('arationale').textContent=p.rationale||'';$('acost').textContent=p.estimated_cost!=null?`Estimated cost: $${Number(p.estimated_cost).toFixed(2)}`:''}async function decide(ok){if(!A)return;let id=A.id;$('approval').classList.add('hidden');await api('/agent/approval/'+id,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({approved:ok})});A=null;setTimeout(load,400)}async function runObjective(){let t=$('objective').value.trim();if(!t)return;$('objective').value='';let d=await api('/agent/v223/command',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({text:t,request_id:crypto.randomUUID()})});alert(d.message);setTimeout(load,500)}async function uploadKnowledge(ev){ev.preventDefault();let f=new FormData();f.append('file',$('kf').files[0]);f.append('category',$('kc').value||'general');f.append('tags',$('kt').value||'');let r=await fetch('/knowledge/upload',{method:'POST',body:f});if(!r.ok)return alert('Upload failed');ev.target.reset();load()}load();setInterval(load,3000)</script></body></html>'''